#include <iostream>
#include <climits>

bool safe_add(int a, int b, int& result) {
    if (b > 0 && a > INT_MAX - b) {
        return false; // overflow
    }
    if (b < 0 && a < INT_MIN - b) {
        return false; // underflow
    }
    result = a + b;
    return true;
}

int main() {
    int a = INT_MAX;
    int b = 1;
    int sum = 0;

    if (safe_add(a, b, sum)) {
        std::cout << "Sum: " << sum << "\n";
    } else {
        std::cout << "Overflow prevented! a=" << a << ", b=" << b << "\n";
    }
    return 0;
}
